import { useState } from "react";
import "./App.css";

function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = input;

    setMessages((prev) => [
      ...prev,
      { role: "user", text: userMessage },
    ]);

    setInput("");
    setLoading(true);

    try {
      const res = await fetch("http://127.0.0.1:8000/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userMessage }),
      });

      const data = await res.json();

      setMessages((prev) => [
        ...prev,
        { role: "bot", text: data.response },
      ]);
    } catch {
      setMessages((prev) => [
        ...prev,
        { role: "bot", text: "Erreur serveur ❌" },
      ]);
    }

    setLoading(false);
  };

  return (
    <div className="container">
      <div className="chat-box">

        <div className="header">
          🏠 Real Estate Assistant
          <span>Conseils immobiliers intelligents</span>
        </div>

        <div className="messages">
          {messages.length === 0 && (
            <div className="welcome">
              💬 Pose une question :
              <ul>
                <li>Est-ce que ce prix est correct ?</li>
                <li>Cette location est-elle rentable ?</li>
                <li>Comment acheter un bien ?</li>
              </ul>
            </div>
          )}

          {messages.map((m, i) => (
            <div key={i} className={`msg ${m.role}`}>
              {m.role === "user" ? "👤" : "🏡"} {m.text}
            </div>
          ))}

          {loading && <div className="msg bot">🏡 Analyse en cours...</div>}
        </div>

        <div className="input-box">
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && sendMessage()}
            placeholder="Ex: Est-ce que 200k€ pour un appartement est correct ?"
          />
          <button onClick={sendMessage}>Envoyer</button>
        </div>

      </div>
    </div>
  );
}

export default App;
